  // --- Settings rebuild (setg*) ---
  setgIntro:
    "ऐप कैसे चलेगा, वो सब यहीं से तय होता है। आराम से देखिए — कुछ काम वापस नहीं हो सकते।",
  setgTabGeneral: "जानकारी",
  setgTabCalendars: "छुट्टियाँ",
  setgTabData: "कॉपी और डेटा",
  setgTabSecurity: "पासवर्ड",

  setgAboutTitle: "इस ऐप के बारे में",
  setgAboutBody:
    "आपका सारा हिसाब सिर्फ इसी कंप्यूटर में रहता है। कहीं बाहर नहीं जाता। अगर यह कंप्यूटर खो जाए या खाली हो जाए, तो हिसाब सिर्फ सेव की हुई कॉपी से ही वापस आएगा — इसलिए “कॉपी और डेटा” से कॉपी बनाते रहिए।",
  setgAboutStorageTitle: "आपका हिसाब कहाँ रखा है",
  setgAboutStorageFile: "इस कंप्यूटर की इस फाइल में:",
  setgAboutStorageBrowser:
    "इसी कंप्यूटर पर, इसी प्रोग्राम के अंदर। समय-समय पर फाइल में कॉपी सेव करते रहिए ताकि एक और कॉपी रहे।",
  setgAboutOtherSettingsTitle: "कुछ सेटिंग कहीं और हैं",
  setgAboutOtherSettingsBody:
    "काम का समय और रविवार का नियम “समय और रविवार” स्क्रीन पर हैं। आइटम और रेट “आइटम और रेट” स्क्रीन पर हैं।",
  setgAboutOtherSettingsLink: "समय और रविवार खोलें",

  setgCalIntro:
    "वे दिन लिखिए जिनमें कोई काम नहीं करता। काम के दिन और सैलरी गिनते समय ऐप इन्हें देखता है।",
  setgCalFactoryTitle: "पूरी फैक्ट्री बंद",
  setgCalFactoryBody:
    "वे दिन जब पूरी फैक्ट्री बंद रहती है। इन दिनों किसी को गैरहाज़िर नहीं गिना जाता।",
