  setgPayDaysLabel: "\u0930\u0935\u093f\u0935\u093e\u0930 \u092a\u0930 \u0905\u0924\u093f\u0930\u093f\u0915\u094d\u0924 \u092a\u0917\u093e\u0930 \u0938\u0947 \u092a\u0939\u0932\u0947 \u0915\u093f\u0924\u0928\u0947 \u0926\u093f\u0928 \u0939\u093e\u091c\u093c\u093f\u0930",
