    "\u092e\u0939\u0940\u0928\u0947 \u092e\u0947\u0902 \u0915\u093f\u0924\u0928\u0947 \u0926\u093f\u0928 \u0939\u093e\u091c\u093c\u093f\u0930 \u0930\u0939\u0928\u0947 \u0915\u0947 \u092c\u093e\u0926 \u0915\u093e\u092e \u0915\u093f\u090f \u0917\u090f \u0930\u0935\u093f\u0935\u093e\u0930 \u0915\u0940 \u0905\u0924\u093f\u0930\u093f\u0915\u094d\u0924 \u092a\u0917\u093e\u0930 \u092e\u093f\u0932\u0947\u0917\u0940\u0964 0 \u0915\u093e \u092e\u0924\u0932\u092c \u0939\u0930 \u0915\u093e\u092e \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0930\u0935\u093f\u0935\u093e\u0930 \u0905\u0924\u093f\u0930\u093f\u0915\u094d\u0924 \u092a\u0917\u093e\u0930 \u0926\u0947\u0917\u093e\u0964 \u091c\u093c\u094d\u092f\u093e\u0926\u093e \u0938\u0947 \u091c\u093c\u094d\u092f\u093e\u0926\u093e 31 \u2014 \u0938\u092c\u0938\u0947 \u0932\u0902\u092c\u0947 \u092e\u0939\u0940\u0928\u0947 \u0915\u0947 \u0926\u093f\u0928\u0964 \u0907\u0938\u0938\u0947 \u092c\u0921\u093c\u0940 \u0938\u0902\u0916\u094d\u092f\u093e \u0915\u092d\u0940 \u092a\u0942\u0930\u0940 \u0928\u0939\u0940\u0902 \u0939\u094b \u0938\u0915\u0924\u0940, \u0924\u094b \u0915\u093f\u0938\u0940 \u0915\u094b \u092d\u0940 \u0905\u0924\u093f\u0930\u093f\u0915\u094d\u0924 \u092a\u0917\u093e\u0930 \u0928\u0939\u0940\u0902 \u092e\u093f\u0932\u0947\u0917\u0940\u0964",
  setgPayTimesLabel: "\u0930\u0935\u093f\u0935\u093e\u0930 \u0915\u0940 \u092a\u0917\u093e\u0930, \u090f\u0915 \u0926\u093f\u0928 \u0915\u0940 \u092a\u0917\u093e\u0930 \u0938\u0947 \u0915\u093f\u0924\u0928\u0947 \u0917\u0941\u0928\u093e",
  setgPayTimesHelp:
    "1 \u0915\u093e \u092e\u0924\u0932\u092c \u0930\u0935\u093f\u0935\u093e\u0930 \u092d\u0940 \u092c\u093e\u0915\u0940 \u0926\u093f\u0928\u094b\u0902 \u091c\u093f\u0924\u0928\u093e \u0939\u0940, \u0915\u0941\u091b \u0905\u0924\u093f\u0930\u093f\u0915\u094d\u0924 \u0928\u0939\u0940\u0902\u0964 1.2 \u0915\u093e \u092e\u0924\u0932\u092c \u0938\u0935\u093e \u090f\u0915 \u0926\u093f\u0928 \u0915\u0940 \u092a\u0917\u093e\u0930\u0964 1 \u0938\u0947 \u0915\u092e \u092f\u0939\u093e\u0901 \u0928\u0939\u0940\u0902 \u091a\u0932\u0947\u0917\u093e: \u0935\u0939 \u0905\u0924\u093f\u0930\u093f\u0915\u094d\u0924 \u0926\u0947\u0928\u0947 \u0915\u0940 \u091c\u0917\u0939 \u091a\u0941\u092a\u091a\u093e\u092a \u0930\u0935\u093f\u0935\u093e\u0930 \u0915\u0940 \u092a\u0917\u093e\u0930 \u0915\u093e\u091f \u0926\u0947\u0917\u093e\u0964 \u091c\u093c\u094d\u092f\u093e\u0926\u093e \u0938\u0947 \u091c\u093c\u094d\u092f\u093e\u0926\u093e 10\u0964",
  setgPayExampleTitle: "\u092a\u0948\u0938\u094b\u0902 \u092e\u0947\u0902 \u0907\u0938\u0915\u093e \u092e\u0924\u0932\u092c",
  setgPayExamplePays:
    "\u091c\u094b \u0935\u0930\u094d\u0915\u0930 \u092e\u0939\u0940\u0928\u0947 \u092e\u0947\u0902 {days} \u0926\u093f\u0928 \u0939\u093e\u091c\u093c\u093f\u0930 \u0930\u0939\u093e \u0914\u0930 \u0930\u0935\u093f\u0935\u093e\u0930 \u0915\u093e\u092e \u0915\u0930\u0924\u093e \u0939\u0948, \u0909\u0938\u0947 \u0909\u0938 \u0930\u0935\u093f\u0935\u093e\u0930 \u0915\u0940 \u090f\u0915 \u0926\u093f\u0928 \u0915\u0940 \u092a\u0917\u093e\u0930 \u0938\u0947 {times} \u0917\u0941\u0928\u093e \u092e\u093f\u0932\u0947\u0917\u093e\u0964 \u20b9{rate} \u0930\u094b\u091c\u093c \u0915\u0940 \u092a\u0917\u093e\u0930 \u092a\u0930 \u0935\u0939 \u0930\u0935\u093f\u0935\u093e\u0930 \u20b9{amount} \u0926\u0947\u0917\u093e\u0964",
  setgPayExampleEvery:
    "\u0939\u0930 \u0915\u093e\u092e \u0915\u093f\u092f\u093e \u0917\u092f\u093e \u0930\u0935\u093f\u0935\u093e\u0930 \u090f\u0915 \u0926\u093f\u0928 \u0915\u0940 \u092a\u0917\u093e\u0930 \u0938\u0947 {times} \u0917\u0941\u0928\u093e \u0926\u0947\u0917\u093e, \u091a\u093e\u0939\u0947 \u0935\u0930\u094d\u0915\u0930 \u0915\u093f\u0924\u0928\u0947 \u092d\u0940 \u0926\u093f\u0928 \u0939\u093e\u091c\u093c\u093f\u0930 \u0930\u0939\u093e \u0939\u094b\u0964 \u20b9{rate} \u0930\u094b\u091c\u093c \u0915\u0940 \u092a\u0917\u093e\u0930 \u092a\u0930 \u0935\u0939 \u0930\u0935\u093f\u0935\u093e\u0930 \u20b9{amount} \u0926\u0947\u0917\u093e\u0964",
  setgPayExampleFlat:
    "{times} \u0917\u0941\u0928\u093e \u092a\u0930 \u0930\u0935\u093f\u0935\u093e\u0930 \u092c\u093f\u0932\u0915\u0941\u0932 \u092c\u093e\u0915\u0940 \u0926\u093f\u0928\u094b\u0902 \u091c\u0948\u0938\u093e \u0939\u0940 \u092e\u093f\u0932\u0947\u0917\u093e \u2014 \u0915\u0941\u091b \u092d\u0940 \u0905\u0924\u093f\u0930\u093f\u0915\u094d\u0924 \u0928\u0939\u0940\u0902\u0964 \u0905\u0924\u093f\u0930\u093f\u0915\u094d\u0924 \u0926\u0947\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u092f\u0939\u093e\u0901 1 \u0938\u0947 \u092c\u0921\u093c\u0940 \u0938\u0902\u0916\u094d\u092f\u093e \u0921\u093e\u0932\u0947\u0902\u0964",
  setgPaySave: "\u0930\u0935\u093f\u0935\u093e\u0930 \u0915\u0940 \u0921\u093f\u092b\u093c\u0949\u0932\u094d\u091f \u0938\u0947\u091f\u093f\u0902\u0917 \u0938\u0947\u0935 \u0915\u0930\u0947\u0902",
  setgPaySaving: "\u0938\u0947\u0935 \u0939\u094b \u0930\u0939\u093e \u0939\u0948\u2026",
  setgPayUndo: "\u092c\u0926\u0932\u093e\u0935 \u0939\u091f\u093e\u090f\u0901",
  setgPaySaved: "\u0930\u0935\u093f\u0935\u093e\u0930 \u0915\u0940 \u0921\u093f\u092b\u093c\u0949\u0932\u094d\u091f \u0938\u0947\u091f\u093f\u0902\u0917 \u0938\u0947\u0935 \u0939\u094b \u0917\u0908\u0964",
