  bkpDueTitle: "\u0915\u0943\u092a\u092f\u093e \u0905\u092a\u0928\u0947 \u0921\u0947\u091f\u093e \u0915\u0940 \u0915\u0949\u092a\u0940 \u0938\u0947\u0935 \u0915\u0940\u091c\u093f\u090f",
  bkpDueBody:
    "\u0906\u092a\u0915\u093e \u0938\u093e\u0930\u093e \u0939\u093f\u0938\u093e\u092c \u2014 \u0932\u094b\u0917, \u0939\u093e\u091c\u093c\u093f\u0930\u0940, \u0915\u093e\u092e \u0914\u0930 \u0938\u0948\u0932\u0930\u0940 \u2014 \u0938\u093f\u0930\u094d\u092b \u0907\u0938\u0940 \u0915\u0902\u092a\u094d\u092f\u0942\u091f\u0930 \u092e\u0947\u0902 \u0939\u0948\u0964 \u0905\u0917\u0930 \u092f\u0939 \u0916\u094b \u0917\u092f\u093e, \u091a\u094b\u0930\u0940 \u0939\u094b \u0917\u092f\u093e \u092f\u093e \u092e\u0930\u092e\u094d\u092e\u0924 \u092e\u0947\u0902 \u091a\u0932\u093e \u0917\u092f\u093e, \u0924\u094b \u0938\u092c \u0915\u0941\u091b \u0909\u0938\u0915\u0947 \u0938\u093e\u0925 \u091a\u0932\u093e \u091c\u093e\u090f\u0917\u093e\u0964 \u090f\u0915 \u0915\u0949\u092a\u0940 \u092a\u0947\u0928 \u0921\u094d\u0930\u093e\u0907\u0935 \u092e\u0947\u0902 \u0930\u0916\u093f\u090f\u0964",
  bkpSaveNow: "\u0905\u092d\u0940 \u0915\u0949\u092a\u0940 \u0938\u0947\u0935 \u0915\u0930\u0947\u0902",
