  bkpSnoozed: "\u0920\u0940\u0915 \u0939\u0948 \u2014 \u0915\u0932 \u092b\u093f\u0930 \u092f\u093e\u0926 \u0926\u093f\u0932\u093e\u092f\u093e \u091c\u093e\u090f\u0917\u093e\u0964",

  bkpScheduleTitle: "\u092f\u093e\u0926 \u0926\u093f\u0932\u093e\u0928\u093e \u0914\u0930 \u0905\u092a\u0928\u0947 \u0906\u092a \u0915\u0949\u092a\u0940 \u092c\u0928\u0928\u093e",
  bkpScheduleBody:
    "\u092f\u0939 \u0910\u092a \u0938\u092c \u0915\u0941\u091b \u0907\u0938\u0940 \u090f\u0915 \u0915\u0902\u092a\u094d\u092f\u0942\u091f\u0930 \u092e\u0947\u0902 \u0930\u0916\u0924\u093e \u0939\u0948\u0964 \u092f\u0939\u093e\u0901 \u0924\u092f \u0915\u0940\u091c\u093f\u090f \u0915\u093f \u0915\u0949\u092a\u0940 \u0938\u0947\u0935 \u0915\u0930\u0928\u0947 \u0915\u0940 \u092f\u093e\u0926 \u0915\u093f\u0924\u0928\u0947 \u0926\u093f\u0928 \u092e\u0947\u0902 \u0926\u093f\u0932\u093e\u0908 \u091c\u093e\u090f, \u0914\u0930 \u0921\u0947\u0938\u094d\u0915\u091f\u0949\u092a \u0910\u092a \u092e\u0947\u0902 \u0907\u0938\u0947 \u0905\u092a\u0928\u0947 \u0906\u092a \u0915\u0949\u092a\u0940 \u092c\u0928\u093e\u0928\u0947 \u0926\u0940\u091c\u093f\u090f\u0964",
  bkpEveryLabel: "\u0907\u0924\u0928\u0947 \u0926\u093f\u0928 \u0915\u0949\u092a\u0940 \u0928 \u092c\u0928\u0947 \u0924\u094b \u092f\u093e\u0926 \u0926\u093f\u0932\u093e\u090f\u0901",
