  bkpAutoTitle: "\u0905\u092a\u0928\u0947 \u0906\u092a \u0915\u0949\u092a\u0940 \u092c\u0928\u0928\u093e",
  bkpAutoDesktopBody:
    "\u092f\u0939 \u0910\u092a \u0906\u092a\u0915\u0940 \u091a\u0941\u0928\u0940 \u0939\u0941\u0908 \u091c\u0917\u0939 \u092e\u0947\u0902 \u0916\u0941\u0926 \u0915\u0949\u092a\u0940 \u0938\u0947\u0935 \u0915\u0930 \u0938\u0915\u0924\u093e \u0939\u0948 \u2014 \u092a\u0947\u0928 \u0921\u094d\u0930\u093e\u0907\u0935 \u092f\u093e \u0907\u0938 \u0915\u0902\u092a\u094d\u092f\u0942\u091f\u0930 \u0915\u0940 \u0926\u0942\u0938\u0930\u0940 \u0921\u094d\u0930\u093e\u0907\u0935\u0964 \u091c\u0917\u0939 \u0906\u092a \u090f\u0915 \u092c\u093e\u0930 \u091a\u0941\u0928\u0924\u0947 \u0939\u0948\u0902\u0964 \u0909\u0938\u0915\u0947 \u092c\u093e\u0926 \u0915\u094b\u0908 \u0935\u093f\u0902\u0921\u094b \u0928\u0939\u0940\u0902 \u0916\u0941\u0932\u0924\u0940 \u0914\u0930 \u0915\u0941\u091b \u092a\u0942\u091b\u093e \u0928\u0939\u0940\u0902 \u091c\u093e\u0924\u093e\u0964",
  bkpAutoWebBody:
    "\u0906\u092a \u092c\u094d\u0930\u093e\u0909\u091c\u093c\u0930 \u0935\u093e\u0932\u093e \u0910\u092a \u091a\u0932\u093e \u0930\u0939\u0947 \u0939\u0948\u0902\u0964 \u092c\u094d\u0930\u093e\u0909\u091c\u093c\u0930 \u0907\u0938 \u0910\u092a \u0915\u094b \u0905\u092a\u0928\u0947 \u0906\u092a \u092b\u093e\u0907\u0932 \u0932\u093f\u0916\u0928\u0947 \u0928\u0939\u0940\u0902 \u0926\u0947\u0924\u093e \u2014 \u0915\u0949\u092a\u0940 \u0924\u092d\u0940 \u0938\u0947\u0935 \u0939\u094b\u0924\u0940 \u0939\u0948 \u091c\u092c \u0906\u092a \u092c\u091f\u0928 \u0926\u092c\u093e\u0924\u0947 \u0939\u0948\u0902\u0964 \u0907\u0938\u0932\u093f\u090f \u092f\u0939\u093e\u0901 \u0906\u092a\u0915\u094b \u092f\u093e\u0926 \u0926\u093f\u0932\u093e\u092f\u093e \u091c\u093e\u090f\u0917\u093e \u0914\u0930 \u090f\u0915 \u092c\u091f\u0928 \u092e\u093f\u0932\u0947\u0917\u093e \u091c\u093f\u0938\u0938\u0947 \u0915\u0949\u092a\u0940 \u0938\u0947\u0935 \u0939\u094b \u091c\u093e\u090f\u0917\u0940\u0964 \u0921\u0947\u0938\u094d\u0915\u091f\u0949\u092a \u0910\u092a \u0905\u092a\u0928\u0947 \u0906\u092a \u0915\u0949\u092a\u0940 \u092c\u0928\u093e \u0938\u0915\u0924\u093e \u0939\u0948\u0964",
