export const messages: Record<AppLocale, Record<MessageKey, string>> = {
  en: { ...en },
  hi,
};

export function interpolate(
  template: string,
  vars: Record<string, string | number>,
): string {
  return template.replace(/\{(\w+)\}/g, (_, key: string) =>
    key in vars ? String(vars[key]) : `{${key}}`,
  );
}
